using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnderTheRain.Combat;
using UnderTheRain.World;

namespace UnderTheRain.Tests.PlayMode
{
    /// <summary>
    /// Prologue flow (P1..P6) generated by PrologueRuinsSetup — kept green through the Story 5.6 rescale.
    /// </summary>
    public class Story54PrologueTests
    {
        private const string PrologueScene = "Prologue_Ruins";
        private const string SewersScene = "Act1_Sewers";

        // Main-path room origins used by PrologueRuinsSetup (floor line at y = 0).
        internal static readonly (string id, float x)[] Rooms =
        {
            ("prologue_metro_platform", 0f),
            ("prologue_gap", 56f),
            ("prologue_debris", 118f),
            ("prologue_duct", 174f),
            ("prologue_hidden_lab", 232f),
            ("prologue_descent", 282f),
        };

        private static RoomTransitionController Transitions => Object.FindFirstObjectByType<RoomTransitionController>();
        private static GameObject Player => GameObject.FindGameObjectWithTag("Player");

        internal static IEnumerator LoadScene(string sceneName)
        {
            SceneManager.LoadScene(sceneName, LoadSceneMode.Single);
            yield return WaitForScene(sceneName);
        }

        internal static IEnumerator WaitForScene(string sceneName, float timeout = 5f)
        {
            float t = 0f;
            while (SceneManager.GetActiveScene().name != sceneName && t < timeout)
            {
                t += Time.unscaledDeltaTime;
                yield return null;
            }
            Assert.AreEqual(sceneName, SceneManager.GetActiveScene().name, $"Scene {sceneName} did not load.");
            yield return null;
            yield return null;
        }

        internal static RoomBounds RoomAt(float x, float y = 1f) => Transitions.FindRoomContaining(new Vector3(x, y, 0f));

        /// <summary>Exit on the room's left/right edge (ignores hatches); with several doors on one side, the lowest.</summary>
        internal static RoomExitTrigger ExitOnSide(RoomBounds room, bool rightSide)
        {
            RoomExitTrigger best = null;
            foreach (var exit in room.GetComponentsInChildren<RoomExitTrigger>(true))
            {
                if (exit.name.StartsWith("Hatch_")) continue;
                if (best == null) { best = exit; continue; }

                float dx = exit.transform.position.x - best.transform.position.x;
                bool moreExtreme = rightSide ? dx > 0.5f : dx < -0.5f;
                bool sameSideLower = Mathf.Abs(dx) <= 0.5f && exit.transform.position.y < best.transform.position.y;
                if (moreExtreme || sameSideLower) best = exit;
            }
            return best;
        }

        internal static void TeleportPlayer(Vector3 position)
        {
            var player = Player;
            player.transform.position = position;
            var body = player.GetComponent<Rigidbody2D>();
            body.position = position;
            body.linearVelocity = Vector2.zero;
        }

        [UnityTest]
        public IEnumerator Prologue_HasSixRoomsInOrder()
        {
            yield return LoadScene(PrologueScene);

            foreach (var (id, x) in Rooms)
            {
                var room = RoomAt(x);
                Assert.IsNotNull(room, $"No room at x={x}.");
                Assert.AreEqual(id, room.RoomId);
            }
        }

        [UnityTest]
        public IEnumerator RightExits_ChainP1ToP6()
        {
            yield return LoadScene(PrologueScene);
            var transitions = Transitions;

            for (int i = 0; i < Rooms.Length - 1; i++)
            {
                var room = RoomAt(Rooms[i].x);
                transitions.SetActiveRoomImmediate(room);
                yield return null;

                var exit = ExitOnSide(room, rightSide: true);
                Assert.IsNotNull(exit, $"{Rooms[i].id} has no right exit.");
                TeleportPlayer(exit.transform.position);

                yield return new WaitForSeconds(0.9f);
                Assert.AreEqual(Rooms[i + 1].id, transitions.CurrentRoom.RoomId, $"Right exit of {Rooms[i].id} should lead to {Rooms[i + 1].id}.");

                yield return new WaitForSeconds(0.6f);
                Assert.AreEqual(Rooms[i + 1].id, transitions.CurrentRoom.RoomId, $"Bounced back out of {Rooms[i + 1].id}.");
            }
        }

        [UnityTest]
        public IEnumerator LeftExits_ChainP6BackToP1()
        {
            yield return LoadScene(PrologueScene);
            var transitions = Transitions;

            for (int i = Rooms.Length - 1; i > 0; i--)
            {
                var room = RoomAt(Rooms[i].x);
                transitions.SetActiveRoomImmediate(room);
                yield return null;

                var exit = ExitOnSide(room, rightSide: false);
                Assert.IsNotNull(exit, $"{Rooms[i].id} has no left exit.");
                TeleportPlayer(exit.transform.position);

                yield return new WaitForSeconds(0.9f);
                Assert.AreEqual(Rooms[i - 1].id, transitions.CurrentRoom.RoomId, $"Left exit of {Rooms[i].id} should lead to {Rooms[i - 1].id}.");

                yield return new WaitForSeconds(0.6f);
                Assert.AreEqual(Rooms[i - 1].id, transitions.CurrentRoom.RoomId, $"Bounced back out of {Rooms[i - 1].id}.");
            }
        }

        [UnityTest]
        public IEnumerator ExitTriggers_CoverOnlyTheDoorwayAtTheRoomEdge()
        {
            // Regression: wide/tall triggers fired before Dante reached the doorway and from above it.
            yield return LoadScene(PrologueScene);

            var points = new[]
            {
                new Vector3(0f, 1f), new Vector3(56f, 1f), new Vector3(118f, 1f), new Vector3(174f, 1f),
                new Vector3(232f, 1f), new Vector3(282f, 1f), new Vector3(280f, 13f), new Vector3(88f, -12f)
            };

            foreach (var p in points)
            {
                var room = Transitions.FindRoomContaining(p);
                Assert.IsNotNull(room, $"No room at {p}.");
                var roomCol = room.GetComponent<BoxCollider2D>();
                float roomLeft = room.transform.position.x + roomCol.offset.x - roomCol.size.x * 0.5f;
                float roomRight = roomLeft + roomCol.size.x;

                foreach (var exit in room.GetComponentsInChildren<RoomExitTrigger>(true))
                {
                    if (exit.name.StartsWith("Hatch_")) continue;
                    var col = exit.GetComponent<BoxCollider2D>();
                    Assert.LessOrEqual(col.size.x, 0.6f + 0.001f, $"{room.RoomId}/{exit.name} trigger too wide.");
                    Assert.LessOrEqual(col.size.y, 2.5f + 0.001f, $"{room.RoomId}/{exit.name} trigger taller than the doorway.");

                    float cx = exit.transform.position.x;
                    float outerEdge = Mathf.Abs(cx - roomLeft) < Mathf.Abs(cx - roomRight)
                        ? cx - col.size.x * 0.5f - roomLeft
                        : roomRight - (cx + col.size.x * 0.5f);
                    Assert.LessOrEqual(Mathf.Abs(outerEdge), 0.05f, $"{room.RoomId}/{exit.name} trigger is not flush with the room edge.");
                }
            }
        }

        [UnityTest]
        public IEnumerator GapRoom_HasNoDamageSources()
        {
            yield return LoadScene(PrologueScene);
            var gap = RoomAt(56f);

            Assert.AreEqual(0, gap.GetComponentsInChildren<Hitbox>(true).Length, "P2 must not hurt the player.");
        }

        [UnityTest]
        public IEnumerator DebrisRoom_HasWorkersBatteryCellAndShotTarget()
        {
            yield return LoadScene(PrologueScene);
            var debris = RoomAt(118f);

            int workers = 0;
            int shotTargets = 0;
            foreach (var health in debris.GetComponentsInChildren<HealthComponent>(true))
            {
                if (health.MaxHealth == 6) workers++;
                // Feet at 5.5: above jump apex (3.2) + baton reach (~1.0).
                if (health.MaxHealth == 2 && health.transform.position.y > 5.5f) shotTargets++;
            }

            Assert.AreEqual(4, workers, "P3 has four Workers on different terrain (flat, slab, under slab, bridge).");
            Assert.AreEqual(1, shotTargets, "P3 needs one high target that teaches the shot.");
            Assert.GreaterOrEqual(debris.GetComponentsInChildren<BatteryCellPickup>(true).Length, 1, "P3 needs a battery cell.");
        }

        [UnityTest]
        public IEnumerator P1_HasNoKittyDuct_P4_HasDuctsAndPanel()
        {
            yield return LoadScene(PrologueScene);

            Assert.AreEqual(0, RoomAt(0f).GetComponentsInChildren<CatExplorationPoint>(true).Length, "P1 has no Kitty duct.");
            var p4Points = RoomAt(174f).GetComponentsInChildren<CatExplorationPoint>(true);
            Assert.GreaterOrEqual(p4Points.Length, 3, "P4 teaches ducts and the offline panel.");

            bool hasPanel = false;
            foreach (var point in p4Points) hasPanel |= point.ExplorationType == CatExplorationType.Terminal;
            Assert.IsTrue(hasPanel, "P4 must include a Terminal-type (panel) interaction.");
        }

        [UnityTest]
        public IEnumerator DescentRoom_OneWayPlatformsClimbableWithoutWallJump()
        {
            yield return LoadScene(PrologueScene);
            var descent = RoomAt(282f, -10f);

            var effectors = descent.GetComponentsInChildren<PlatformEffector2D>(true);
            Assert.GreaterOrEqual(effectors.Length, 5, "P6 needs stacked one-way platforms.");

            var ys = new float[effectors.Length];
            for (int i = 0; i < effectors.Length; i++) ys[i] = effectors[i].transform.position.y;
            System.Array.Sort(ys);
            for (int i = 1; i < ys.Length; i++)
            {
                Assert.LessOrEqual(ys[i] - ys[i - 1], 3.0f, "One-way platforms too far apart to climb back.");
            }
        }

        [UnityTest]
        public IEnumerator SewersWestExit_ArrivesAtDescentBottom()
        {
            yield return LoadScene(SewersScene);
            var shelter = Transitions.CurrentRoom;
            Assert.AreEqual("sewers_initial_shelter", shelter.RoomId);

            var westExit = ExitOnSide(shelter, rightSide: false);
            TeleportPlayer(westExit.transform.position);

            yield return WaitForScene(PrologueScene);
            yield return new WaitForSeconds(0.1f);

            Assert.AreEqual("prologue_descent", Transitions.CurrentRoom.RoomId);
            Assert.AreEqual(293.4f, Player.transform.position.x, 0.5f);
            Assert.Less(Player.transform.position.y, -30f, "Dante should arrive at the bottom of the shaft.");
        }
    }
}
